<script setup lang="ts">
import { computed, onMounted } from 'vue'; import { useRouter } from 'vue-router'; import { useB1Store } from '../stores/b1'
const b1 = useB1Store(); const router = useRouter(); const home = computed(() => b1.home); const tasks = computed(() => home.value?.dailyStream.tasks ?? []); onMounted(() => { b1.restore(); void b1.loadHome() })
function finish(id: string): void { b1.completeTask(id) }
</script>
<template><section class="page-stack" aria-labelledby="today-title"><div class="hero-panel"><div><p class="eyebrow">TODAY'S LOOP</p><h2 id="today-title">今天完成一个小闭环。</h2><p>新内容、复习和错题会按优先级排在一起，完成后会留下可恢复的进度。</p></div><div class="progress-ring"><strong>{{ b1.todayProgress }}%</strong><small>今日进度</small></div></div><div class="grid grid--two"><article class="info-card"><span class="card-kicker">学习连续天数</span><h3>{{ home?.streakDays ?? 0 }} 天</h3><p>保持稳定比一次投入很多更重要。</p></article><article class="info-card"><span class="card-kicker">今日目标</span><h3>{{ home?.dailyStream.targetMinutes ?? 15 }} 分钟</h3><p>已完成 {{ home?.dailyStream.completedMinutes ?? 0 }} 分钟。</p></article></div><article class="task-list"><div class="section-heading"><div><p class="card-kicker">DAILY STREAM</p><h3>今日任务</h3></div><button class="button button--secondary" type="button" @click="router.push({ name: 'learn-session' })">继续学习</button></div><div v-for="task in tasks" :key="task.id" class="task-row" :class="{ completed: task.completed }"><span class="task-icon">{{ task.kind === 'NEW' ? '＋' : task.kind === 'REVIEW' ? '↻' : '!' }}</span><div><strong>{{ task.title }}</strong><p>{{ task.description }} · {{ task.minutes }} 分钟</p></div><button class="button button--ghost" type="button" :disabled="task.completed" @click="finish(task.id)">{{ task.completed ? '已完成' : '完成' }}</button></div></article><p v-if="b1.lastError" class="error-text" role="alert">{{ b1.lastError }}</p></section>
